  it('IMP05-RULES-09 · Consultar con teclado y distintos tamaños → conserva lectura y mide la pantalla completa', () => {
    prepare({ history: true }).then((context) => {
      const samples: number[] = [];
      let firstNavigationMs = 0;
      for (let index = 0; index <= 50; index++) {
        let started = 0;
        cy.then(() => {
          started = performance.now();
        });
        visitAs(context.admin, path(context));
        cy.get('[data-cy="rule-effective"]').should('have.length', 3);
        cy.get('[data-cy="rule-version-row"]').should('have.length', 20);
        cy.then(() => {
          const elapsed = performance.now() - started;
          if (index === 0) firstNavigationMs = elapsed;
          else samples.push(elapsed);
        });
      }
      cy.then(() =>
        cy.task<{ p95Ms: number; samples: number }>(
          'rules:performance',
          {
            organizationId: context.organizationId,
            firstNavigationMs,
            samples,
          },
          { log: false },
        ),
      ).then((result) => {
        expect(result.samples).to.equal(50);
        expect(result.p95Ms).to.be.lessThan(3000);
      });
      for (const { width, height, name } of [
        { width: 1440, height: 900, name: 'desktop' },
        { width: 768, height: 1024, name: 'tablet' },
        { width: 390, height: 844, name: 'mobile' },
      ]) {
        cy.viewport(width, height);
        cy.window({ log: false }).should((window) => {
          expect(window.innerWidth, `${name}: ancho del viewport`).to.equal(
            width,
          );
          expect(window.innerHeight, `${name}: alto del viewport`).to.equal(
            height,
          );
        });
        cy.document({ log: false }).should((document) => {
          expect(
            document.documentElement.scrollWidth,
            `${name}: sin desbordamiento horizontal de la página`,
          ).to.be.at.most(document.documentElement.clientWidth);
        });
        effective('INACTIVITY')
          .should('be.visible')
          .and('have.attr', 'data-rule-id', context.activeRuleId!);
        cy.scrollTo('top');
        cy.screenshot(`imp05-rules-${name}`, {
          capture: 'viewport',
          overwrite: true,
          log: false,
        });
        cy.get('[data-cy="rule-create"]').focus().should('be.focused');
        pressEnterInChrome();
        cy.get('[role="dialog"]').should('be.visible');
        cy.get('[name="type"]').focus().should('be.focused');
        cy.get('[role="dialog"] button[aria-label="Cerrar diálogo"]').click();
        cy.get('[data-cy="rule-create"]').should('be.focused');
      }
    });
  });
